import { z } from "zod";import { db,json,requireApiUser } from "../../_shared";
const schema=z.object({imageUrl:z.string().url(),sourceUrl:z.string().url(),note:z.string().max(500).default("")});
export async function POST(request:Request){const user=await requireApiUser();try{const input=schema.parse(await request.json()),id=crypto.randomUUID(),now=new Date().toISOString();await db().prepare("INSERT INTO assets (id,user_id,asset_type,external_url,source_name,source_url,license_status,risk_level,tags,metadata,created_at) VALUES (?,?,?,?,?,?, 'unknown','yellow','[]',?,?)").bind(id,user.userId,"external_link",input.imageUrl,input.note||"外部图片",input.sourceUrl,JSON.stringify({note:input.note}),now).run();return json({id},{status:201})}catch(error){return json({error:error instanceof Error?error.message:"保存失败"},{status:422})}}
